function missionMarkup(player){const mission=player.mission,progress=player.missionProgress??{};if(!mission)return '<div class="mission-progress mission-inactive" aria-label="本輪沒有使命"><span title="群羊使命">🐑 <b>—</b></span><span title="糧食使命">🌾 <b>—</b></span><span title="金錢使命">💰 <b>—</b></span></div>';const items=[['sheep','🐑','群羊'],['food','🌾','糧食'],['money','💰','金錢']].map(([type,icon,label])=>{const current=Math.min(progress[type]??0,mission[type]??0),required=mission[type]??0,complete=current>=required;return `<span class="${complete?'mission-complete':''}" title="${label}使命：${current}/${required}">${icon} <b>${current}/${required}</b></span>`;});return `<div class="mission-progress" aria-label="使命進度：${items.map((_,index)=>`${['群羊','糧食','金錢'][index]} ${Math.min(progress[['sheep','food','money'][index]]??0,mission[['sheep','food','money'][index]]??0)}/${mission[['sheep','food','money'][index]]??0}`).join('、')}">${items.join('')}</div>`;}
