function placeTopInfo(node){const anchor=$('.corruption-hud'),rect=anchor?.getBoundingClientRect?.(),width=Number(globalThis.innerWidth);if(!node?.style?.setProperty||!rect||!width)return;const set=(property,value)=>node.style.setProperty(property,value,'important'),x=width/32*12,y=rect.top+rect.height/2,rows=[...node.children],place=(row,top,offset)=>{if(!row?.style?.setProperty)return;row.style.setProperty('position','fixed','important');row.style.setProperty('left',`${x-offset}px`,'important');row.style.setProperty('top',`${top}px`,'important');row.style.setProperty('transform','translateY(-50%)','important');row.style.setProperty('width','max-content','important');row.style.setProperty('margin','0','important');row.style.setProperty('text-align','left','important');};set('position','fixed');set('left','0');set('top','0');set('z-index','42');set('width','0');set('height','0');set('overflow','visible');set('transform','none');place(rows[0],y,8.5);place(rows[1],y+24,8);place(rows[2],y+48,8);node.querySelectorAll('.stats,.mission-progress').forEach(row=>{row.style.setProperty('display','flex','important');row.style.setProperty('align-items','center','important');row.style.setProperty('justify-content','flex-start','important');});}
function renderSeats(state){const human=state.players[0],opponents=state.players.slice(1),targets=['#seat-left','#seat-top','#seat-right'];opponents.forEach((player,index)=>{const el=$(targets[index]);el.className=`seat ${targets[index].slice(1)} ${state.currentPlayer===player.playerId?'current':''} ${player.hasNormalAction?'':'inactive'}`;el.innerHTML=index===1?'':playerMarkup(player,state);});const topInfo=$('#seat-top-info'),topPlayer=opponents[1];if(topInfo&&topPlayer){topInfo.className=`seat-top-info ${state.currentPlayer===topPlayer.playerId?'current':''} ${topPlayer.hasNormalAction?'':'inactive'}`;topInfo.innerHTML=playerMarkup(topPlayer,state);placeTopInfo(topInfo);}const humanEl=$('#seat-human');humanEl.className=`human-meta ${state.currentPlayer===human.playerId?'current':''}`;humanEl.innerHTML=playerMarkup(human,state);const reveal=state.lastRevelation;if(reveal&&reveal.id!==lastRevelationId){lastRevelationId=reveal.id;const cards=(reveal.definitionIds??[]).map(definitionId=>definitionTitle(getDefinition({definitionId}))).join('、');showToast(`揭露 I：${playerName(state,reveal.playerId)} 公開抽到 ${cards}`,'warning');}}
function renderJudgments(state){const host=$('#judgment-bar');if(!host)return;const active=(state.visualQaJudgments??Object.values(state.activeJudgments??{})).map(getJudgmentDefinition);host.replaceChildren(...active.map(judgment=>{const item=document.createElement('button');item.type='button';item.className='judgment-pill';item.title=`短按查看：${judgment.domain}｜${judgment.text}`;item.setAttribute('aria-label',`查看審判 ${judgment.name} 的詳細資訊`);item.textContent=judgment.name;item.addEventListener('click',()=>showJudgmentDetail(judgment.id));return item;}));host.hidden=!active.length;const latest=state.lastJudgment;if(latest&&latest.judgmentId!==lastJudgmentId){lastJudgmentId=latest.judgmentId;const judgment=getJudgmentDefinition(latest.judgmentId),replaced=latest.replacedJudgmentId?`，覆蓋 ${getJudgmentDefinition(latest.replacedJudgmentId).name}`:'';showToast(`審判降臨：${judgment.name}${replaced}`,'warning');}}
function render(state,nextActions,nextToken){currentState=state;actions=nextActions;token=nextToken;const human=state.players[0],resource=state.currentResource?`${names[state.currentResource.type]} ${state.currentResource.number}`:'自由出牌',corruption=Number.isFinite(state.corruption)?state.corruption:0,visibleDeckCount=state.deck.filter(card=>card.definitionId!=='death').length,divisionChoices=nextActions.filter(action=>action.type==='resolveDivisionRecipient'),divisionTest=nextActions.find(action=>action.type==='divisionQaGain'),revealedBlindnessAction=state.pendingBlindness?.playerId===human.playerId?nextActions.find(action=>action.type==='playMiracle'&&action.instanceId===state.pendingBlindness.instanceId):null;$('#round-display').textContent=`第 ${state.round} 輪`;$('#status').innerHTML=`<span>牌庫 <strong>${visibleDeckCount}</strong></span><span>棄牌 <strong>${state.discardPile.length}</strong></span><span>場內 <strong>${state.playedArea.length}</strong></span><span>目前物資 <strong>${resource}</strong></span>`;$('#current-resource-display').textContent=resource;const deckCount=$('#resource-deck-count'),discardCount=$('#discard-pile-count');if(deckCount)deckCount.textContent=String(visibleDeckCount);if(discardCount)discardCount.textContent=String(state.discardPile.length);const corruptionDisplay=$('#corruption-value');if(corruptionDisplay)corruptionDisplay.textContent=String(corruption);renderJudgments(state);renderCurrentCard(state);renderSeats(state);renderHand(state);renderSelectionActions(state);renderDeathPresentation(state);const redrawAction=nextActions.find(action=>action.type==='redraw'),deathSkipAction=nextActions.find(action=>action.type==='deathSkip'),deathProgress=state.phase==='deathRound'?deathRoundProgress(state):null;if(state.gameOver)$('#instruction').textContent=`爭局結束 · 勝者 ${state.winner.map(id=>playerName(state,id)).join('、')}`;else if(revealedBlindnessAction&&state.currentPlayer===human.playerId)$('#instruction').textContent='蒙蔽翻出未知功能牌，正在進入其效果。';else if(divisionChoices.length)$('#instruction').textContent=`分裂生效：選擇 1 名符合條件的玩家，額外獲得 ${state.pendingDivision?.bonus??0} 點火種。`;else if(divisionTest)$('#instruction').textContent='分裂 QA：先執行測試效果，讓你單次獲得 5 點火種。';else if(deathProgress)$('#instruction').textContent=`死亡輪：最後行動 ${deathProgress.current} / ${deathProgress.total}。`;else if(redrawAction&&state.currentPlayer===human.playerId)$('#instruction').textContent='沒有可出的牌。你可以整備：棄置全部手牌並抽 2 張。';else if(state.currentPlayer===human.playerId)$('#instruction').textContent='輪到你。短按放大卡牌、長按查看詳情，或直接拖向中央出牌。';else $('#instruction').textContent=`等待 ${playerName(state,state.currentPlayer)} 行動…`;$('#actions').replaceChildren();if(!state.gameOver&&state.currentPlayer===human.playerId)renderHumanActions(state);$('#round-result').textContent=state.lastRoundResult?`第 ${state.lastRoundResult.round} 輪 · 使徒 ${state.lastRoundResult.apostle?playerName(state,state.lastRoundResult.apostle):'無'} · +${state.lastRoundResult.reward} 火種`:'火種仍在等待新的使徒';if(revealedBlindnessAction)queueMicrotask(()=>{if(currentState===state&&token===nextToken&&currentState.pendingBlindness?.instanceId===revealedBlindnessAction.instanceId)controller.act(revealedBlindnessAction,nextToken);});}
function actionButton(label,action,emphasized=false){const button=document.createElement('button');button.textContent=label;if(emphasized)button.classList.add('primary-action');button.addEventListener('click',()=>{selectedInstanceId=null;clearClickPreview();if(action.type==='redraw'){$('#hand').classList.add('redealing');setTimeout(()=>controller.act(action,token),230);}else controller.act(action,token);});$('#actions').append(button);}
function openWarDiscard(){const choices=actions.filter(action=>action.type==='warDiscard'),max=Math.max(...choices.map(action=>action.discardInstanceIds.length)),picked=[];const overlay=document.createElement('div');overlay.className='war-discard-overlay';overlay.innerHTML=`<article class="war-discard-panel"><span>審判 · 爭戰</span><h2>選擇 ${max===1?'1':'1 至 2'} 張手牌棄置</h2><p>將抽取等量牌${currentState.players[0].effects.some(card=>card.definitionId==='miracle-13')?'；《在黎明前叩門》會額外抽 1 張並要求棄置 1 張。':''}</p><div class="war-discard-cards"></div><div class="war-discard-actions"><small></small><button disabled>確認棄牌</button><button type="button">取消</button></div></article>`;const host=overlay.querySelector('.war-discard-cards'),confirm=overlay.querySelector('.war-discard-actions button'),note=overlay.querySelector('.war-discard-actions small'),cancel=overlay.querySelector('.war-discard-actions button:last-child');const update=()=>{for(const button of host.children)button.classList.toggle('picked',picked.includes(button.dataset.id));const valid=choices.find(action=>action.discardInstanceIds.length===picked.length&&action.discardInstanceIds.every(id=>picked.includes(id)));confirm.disabled=!valid;note.textContent=`已選 ${picked.length} / ${max} 張`;confirm.onclick=()=>{if(valid){overlay.remove();controller.act(valid,token);}};};for(const card of currentState.players[0].hand){const definition=getDefinition(card),button=document.createElement('button');button.type='button';button.dataset.id=card.instanceId;button.innerHTML=`<img src="${definition.image}" alt=""><small>${definition.name??`${names[definition.type]} ${definition.number}`}</small>`;button.onclick=()=>{const index=picked.indexOf(card.instanceId);if(index>=0)picked.splice(index,1);else if(max===1)picked.splice(0,picked.length,card.instanceId);else if(picked.length<max)picked.push(card.instanceId);else{picked.shift();picked.push(card.instanceId);}update();};host.append(button);}cancel.onclick=()=>overlay.remove();document.body.append(overlay);update();}
function renderHumanActions(){const divisionTest=actions.find(action=>action.type==='divisionQaGain');if(divisionTest){actionButton('測試效果：獲得 5 點火種',divisionTest,true);return;}const divisionChoices=actions.filter(action=>action.type==='resolveDivisionRecipient');if(divisionChoices.length){for(const action of divisionChoices)actionButton(`分裂：額外給 ${playerName(currentState,action.recipientPlayerId)} ${currentState.pendingDivision?.bonus??0} 點火種`,action,true);return;}if(actions.some(action=>action.type==='warDiscard')){const button=document.createElement('button');button.textContent='爭戰：棄牌並抽等量';button.classList.add('primary-action');button.onclick=openWarDiscard;$('#actions').append(button);}const automatic=actions.find(action=>!['playResource','playMiracle','playBlindnessPile','warDiscard'].includes(action.type));if(!automatic)return;const labels={redraw:'整備：棄牌並抽 2 張',deathSkip:'死亡輪：略過最後行動',endParticipation:'退出本輪爭局',endEmptyHand:'空手：結束參與'};actionButton(labels[automatic.type],automatic,automatic.type==='redraw'||automatic.type==='deathSkip');}
window.addEventListener('pointermove',movePointer,{passive:false});window.addEventListener('pointerup',endPointer,{passive:false});window.addEventListener('pointercancel',endPointer,{passive:false});
window.addEventListener('resize',()=>{if(currentState)renderSeats(currentState);});
window.addEventListener('keydown',event=>{if(event.key!=='Escape')return;if(!$('#grace-overlay').hidden)return closeGraceChoice();if(!$('#detail-overlay').hidden)return hideDetail();if(selectedInstanceId&&currentState){selectedInstanceId=null;clearClickPreview();renderSelectionActions(currentState);}});
document.querySelectorAll('[data-close="detail"]').forEach(element=>element.addEventListener('click',hideDetail));$('#grace-cancel').addEventListener('click',()=>{closeGraceChoice();if(currentState)renderSelectionActions(currentState);});
function setupLayoutGrid(){const labels=$('#layout-grid-labels'),toggle=$('#layout-grid-toggle'),grid=$('#layout-grid');for(let x=0;x<=32;x+=4){const label=document.createElement('span');label.className='grid-x';label.textContent=x;label.style.left=`${x/32*100}%`;labels.append(label);}for(let y=0;y<=18;y+=3){const label=document.createElement('span');label.className='grid-y';label.textContent=y;label.style.top=`${y/18*100}%`;labels.append(label);}toggle.addEventListener('click',()=>{const visible=!grid.classList.toggle('is-hidden');toggle.setAttribute('aria-pressed',String(visible));});}
setupLayoutGrid();
const judgmentQaRoute=new URLSearchParams(globalThis.location?.search??'').get('qa'),judgmentQaSeed=judgmentQaRoute==='burning-city'||judgmentQaRoute==='burning-city-test'?'burning-city-test':judgmentQaRoute==='reaction-five'?'reaction-five-preview':judgmentQaRoute==='judgment-layout'?'judgment-layout-preview':judgmentQaRoute==='judgment-war'?'judgment-war-preview':judgmentQaRoute==='judgment-division'?'judgment-division-preview':judgmentQaRoute==='judgment-sinking'?'judgment-sinking-preview':judgmentQaRoute==='judgment-blindness'?'judgment-blindness-preview':judgmentQaRoute==='judgment-disorder-2'?'judgment-disorder-2-preview':judgmentQaRoute==='judgment-disorder'?'judgment-disorder-preview':null,initialSeed=judgmentQaSeed??'recovery-preview',layoutQaJudgments=Object.freeze(['disorder-1','blindness-1','war-1','overturn-1','division-1']);const controller=new GameController({render,delay:aiDelay});globalThis.__shepherdController=controller;$('#restart').addEventListener('click',event=>{event.preventDefault();selectedInstanceId=null;lastJudgmentId=null;clearClickPreview();closeGraceChoice();hideDetail();document.querySelector('.war-discard-overlay')?.remove();controller.restart(judgmentQaSeed??($('#restart').dataset.seed=`${Date.now()}`));if(judgmentQaRoute==='judgment-layout'){controller.state.visualQaJudgments=layoutQaJudgments;controller.safeRender();}});controller.start(initialSeed);if(judgmentQaRoute==='judgment-sinking'){controller.logAi('審判〈沉淪 I〉降臨：用《積財寶在地上》選擇賽芙；你、賽芙、賈斯會分別從 10／25／15 變為 6／15／9，第四人維持 5。');controller.safeRender();}if(judgmentQaRoute==='judgment-blindness'){controller.logAi('審判〈蒙蔽 I〉降臨：先選神蹟或災難，系統會隨機翻出該類的一張。完成後自動切換至〈蒙蔽 II〉，改為所有功能牌混在同一覆蓋牌堆。');controller.safeRender();}if(judgmentQaRoute==='judgment-layout'){controller.state.visualQaJudgments=layoutQaJudgments;controller.safeRender();}
